Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #000; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 200;
        const LANE_WIDTH = 8;
        const CAR_WIDTH = 4;
        const CAR_HEIGHT = 2;
        const CAR_LENGTH = 8;
        const FINISH_LINE_Z = 100;

        // Animation speeds
        const BLUE_SPEED_BASE = 0.8;
        const RED_SPEED_BASE = 0.6;
        const RED_ACCELERATION = 0.002; // How much faster it gets per frame
        const RESET_SPEED = 1.5;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 50, 300);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        dirLight.shadow.camera.top = 100;
        dirLight.shadow.camera.bottom = -100;
        dirLight.shadow.camera.left = -100;
        dirLight.shadow.camera.right = 100;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(400, 600);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x228B22 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.1;
        ground.receiveShadow = true;
        scene.add(ground);

        // Finish Line
        const finishLineGeo = new THREE.PlaneGeometry(40, 10);
        // Create a checkerboard texture for the finish line
        const canvas = document.createElement('canvas');
        canvas.width = 64;
        canvas.height = 64;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = 'white';
        ctx.fillRect(0, 0, 64, 64);
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, 32, 32);
        ctx.fillRect(32, 32, 32, 32);
        const texture = new THREE.CanvasTexture(canvas);
        texture.wrapS = THREE.RepeatWrapping;
        texture.wrapT = THREE.RepeatWrapping;
        texture.repeat.set(10, 1);

        const finishLineMat = new THREE.MeshStandardMaterial({ map: texture });
        const finishLine = new THREE.Mesh(finishLineGeo, finishLineMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.1, FINISH_LINE_Z);
        scene.add(finishLine);

        // --- Car Creation ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Main Body
            const bodyGeo = new THREE.BoxGeometry(CAR_WIDTH, CAR_HEIGHT, CAR_LENGTH);
            const bodyMat = new THREE.MeshStandardMaterial({ color: color });
            const body = new THREE.Mesh(bodyGeo, bodyMat);
            body.position.y = CAR_HEIGHT / 2;
            body.castShadow = true;
            body.receiveShadow = true;
            carGroup.add(body);

            // Cabin (Top)
            const cabinGeo = new THREE.BoxGeometry(CAR_WIDTH - 1, CAR_HEIGHT / 2, CAR_LENGTH / 2);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 }); // Dark grey
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = CAR_HEIGHT + CAR_HEIGHT / 4;
            cabin.position.z = -1;
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(1, 1, 1, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
            const wheelPositions = [
                { x: -2, z: 2 }, { x: 2, z: 2 },
                { x: -2, z: -2 }, { x: 2, z: -2 }
            ];

            wheelPositions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 1, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            return carGroup;
        }

        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);

        // Initial Positions
        redCar.position.set(-10, 0, -50);
        blueCar.position.set(10, 0, -50);

        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation State ---
        let redPos = -50;
        let bluePos = -50;
        let redSpeed = RED_SPEED_BASE;
        let blueSpeed = BLUE_SPEED_BASE;
        let isResetting = false;
        let raceFinished = false;

        // Camera offset
        const cameraOffset = new THREE.Vector3(0, 20, 40);

        // --- Resize Handler ---
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // --- Animation Loop ---
        function animate() {
            requestAnimationFrame(animate);

            if (!isResetting) {
                // Move cars
                redPos += redSpeed;
                bluePos += blueSpeed;

                // Accelerate Red Car
                redSpeed += RED_ACCELERATION;

                // Update positions
                redCar.position.z = redPos;
                blueCar.position.z = bluePos;

                // Check for Red Car Win (Crosses finish line)
                if (redPos > FINISH_LINE_Z) {
                    isResetting = true;
                }
            }

            // Reset Logic
            if (isResetting) {
                redSpeed = RED_SPEED_BASE;
                redPos -= RESET_SPEED;
                bluePos -= RESET_SPEED;

                // Keep them aligned if blue is way ahead
                if (bluePos > FINISH_LINE_Z) bluePos = -50;
                if (redPos > FINISH_LINE_Z) redPos = -50;

                // Unreset when back at start
                if (redPos < -60) {
                    isResetting = false;
                }
            }

            // Camera Follow Logic
            // Target position: midpoint between cars + offset
            const midZ = (redPos + bluePos) / 2;
            const targetCamPos = new THREE.Vector3(0, 15, midZ + 40);

            // Smoothly interpolate camera
            camera.position.lerp(targetCamPos, 0.05);
            camera.lookAt(0, 0, midZ);

            renderer.render(scene, camera);
        }

        animate();
    </script>
</body>
</html>
```
